contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;

        assert(
            balanceAfter == balanceBefore + amount &&
            contractBalanceAfter == contractBalanceBefore + amount &&
            testBalanceAfter == testBalanceBefore - amount
        );
    }

    receive() external payable {}
}

